import React, { useState, useRef, useEffect } from 'react';

// Create the usePrevious custom hook here
const usePrevious = (value) => {
  // Initialize a ref here
  const ref = useRef();

  // Add useEffect here
  useEffect(() => {
    ref.current = value;
  });

  // Return the previous value here
  return ref.current;
};

// Create the App component here
const App = () => {
  // Initialize state for count here
  const [count, setCount] = useState(0);

  // Call usePrevious here
  const previousCount = usePrevious(count);

  return null;
};

